	ZAnim.AddCmd("ai::HOLD", CTHold::Parse, CTHold::Begin, CTHold::Tick, CTHold::End);
	ZAnim.AddCmd("ai::INSTATE", CTInState::Parse, NULL, CTInState::Tick, NULL);
	ZAnim.AddCmd("ai::INVIEW", CTInView::Parse, NULL, CTInView::Tick, NULL);
